.set-or-append Tabela_Alertas <|
V2
// 1. Procurar as portas abertas
| where Tipo_de_Evento == "Door Open" and toint(Valor) == 1
// 2. Cruzar com a velocidade no mesmo segundo
| join kind=leftsemi (
    V2
    | where Tipo_de_Evento == "Speed" and todouble(Valor) > 10
) on Comboio, Carruagem, Datahora_Evento
| extend Tipo_Alerta = "PERIGO: Porta aberta com comboio em movimento"
// 3. A MAGIA (Anti-Join): Só deixa passar as linhas que AINDA NÃO ESTÃO na Tabela_Alertas
| join kind=leftanti (
    Tabela_Alertas
    | where Tipo_Alerta == "PERIGO: Porta aberta com comboio em movimento"
) on Comboio, Carruagem, Datahora_Evento
